int dp[1<<20][77];
int b[77] , n;
int go(int mask , int i) {
  int cnt = __builtin_popcount(mask);
  if(i == n) {
    if(cnt != 0 && (1<<cnt)-1 == mask)
      return 1;
    return 0;
  }
  if(dp[mask][i] != -1) return dp[mask][i];

  int ret = 0;
  if(b[i] == 0)
    ret = go(mask , i+1);
  else {
    int num = 0;
    int j = i;
    while(1) {
      num *= 2;
      num += b[j];
      if(num > 20) break;
      //if(!(mask & (1<<(num-1))))
      ret = add(ret , go(mask | (1<<(num-1)) , j+1));
      j ++;
      if(j == n) break;
    }
    if(cnt != 0 && mask == (1<<cnt)-1)
      ret ++;
  }
  return dp[mask][i] = ret;
}

