int dijkstra(int root){
  for(int i=1;i<=n;i++)d[i]=INF,P[i].clear();
  Dominator::reset(n);d[root]=0;SET(vis,0);
  set<pair<LL,int>> S;S.insert({d[root],root});
  while(!S.empty()){
    int u = S.begin()->S;
    S.erase(S.begin());
    if(vis[u])continue;
    vis[u]=1;
    for(auto w:g[u])
      if(d[u] + w.S < d[w.F]){
        d[w.F] = d[u] + w.S;
        P[w.F].clear();P[w.F].PB(u);
        S.insert({d[w.F],w.F});
      }
      else if(d[u]+w.S==d[w.F])
        P[w.F].PB(u);
  }
  for(int i=1;i<=n;i++)
    for(auto j : P[i])
        Dominator::addEdge(j,i);
  Dominator::get(n,root,sub);
  int mx = 0;
  for(int i=1;i<=n;i++)
    if(i!=root)
      mx = max(mx,sub[i]);
  return mx;
}
